// Manifest of the 48 realization photos from the client's Google Photos album "realizacje"
// (source: _tresci/obrazy/realizacje/, details and album numbers: _tresci/obrazy/INDEX.md).
// Files are generated by scripts/images.mjs into public/img/realizacje/:
//   <file>.webp      – max 1600 px on the long edge (width/height below)
//   <file>-800.webp  – max 800 px on the long edge (smallWidth/smallHeight)
//
// Locations, materials and systems of these jobs are NOT known yet – descriptions only say what is
// visible. Do not add a town or a product system to a caption without the client's confirmation.
// `publish: false` marks files that are not photos of a job (marketing graphic, logo).

export type Stage = 'wykonczone' | 'stan-surowy' | 'proces' | 'grafika';

/** Tags used to pick photos for pages. Category slugs where it fits, plus a few motifs. */
export type PhotoTag =
  | 'okna'
  | 'przeszklenia'
  | 'drzwi-tarasowe'
  | 'drzwi-zewnetrzne'
  | 'drzwi-wewnetrzne'
  | 'bramy-garazowe'
  | 'montaz'
  | 'widok-z-wnetrza'
  | 'detal'
  | 'elewacja'
  | 'kamienica';

export interface RealizacjaZdjecie {
  /** ASCII base name, e.g. "okno-narozne-antracyt-bez-slupka" */
  file: string;
  /** original file name in the album / _tresci folder */
  source: string;
  /** number of the item in the Google Photos album (see INDEX.md) */
  albumNo: number;
  /** date the photo was taken (from the album) */
  date: string;
  width: number;
  height: number;
  orientation: 'pionowe' | 'poziome' | 'kwadrat';
  /** what the photo shows (internal description) */
  description: string;
  /** ready-to-use alt text */
  alt: string;
  stage: Stage;
  tags: PhotoTag[];
  /** quality rating from docs/marka.md §7: TAK = premium, WARUNKOWO = supporting sections only */
  rating: 'TAK' | 'WARUNKOWO' | 'NIE';
  publish: boolean;
}

type Raw = Omit<RealizacjaZdjecie, 'orientation'>;

