const orientationOf = (w: number, h: number): RealizacjaZdjecie['orientation'] =>
  Math.abs(w - h) / Math.max(w, h) < 0.05 ? 'kwadrat' : w > h ? 'poziome' : 'pionowe';

export const zdjecia: RealizacjaZdjecie[] = raw.map((z) => ({ ...z, orientation: orientationOf(z.width, z.height) }));

/** Path of the large file, e.g. /img/realizacje/okno-narozne-antracyt-bez-slupka.webp */
export const photoSrc = (z: Pick<RealizacjaZdjecie, 'file'>) => `/img/realizacje/${z.file}.webp`;
/** Path of the 800 px file */
export const photoSrcSmall = (z: Pick<RealizacjaZdjecie, 'file'>) => `/img/realizacje/${z.file}-800.webp`;
/** Size of the 800 px file */
export const smallSize = (z: Pick<RealizacjaZdjecie, 'width' | 'height'>) => {
  const k = Math.min(1, 800 / Math.max(z.width, z.height));
  return { width: Math.round(z.width * k), height: Math.round(z.height * k) };
};

export const photoByFile = (file: string) => zdjecia.find((z) => z.file === file);

/** Published photos with any of the tags, best (TAK) first. */
export const photosByTag = (tags: PhotoTag[], limit = 6) =>
  zdjecia
    .filter((z) => z.publish && z.tags.some((t) => tags.includes(t)))
    .sort((a, b) => (a.rating === b.rating ? 0 : a.rating === 'TAK' ? -1 : 1))
    .slice(0, limit);
